-- Drafts: half-written messages that have not been sent yet.
--
-- Why not put them in the messages table:
--   1) messages.direction has `CHECK (direction IN ('inbound','outbound'))`;
--      adding 'draft' would require rebuilding the whole table (SQLite cannot alter a CHECK constraint);
--   2) drafts have no delivery semantics — no message_id / thread_id / status / resend_id —
--      and mixing them in would force **every** folder query to additionally exclude draft rows;
--   3) a draft's primary key is **generated by the frontend** (the id exists as soon as the compose modal opens), so autosave uses upsert
--      and no "create first, then get the id" round trip is needed.

CREATE TABLE IF NOT EXISTS drafts (
    id          TEXT PRIMARY KEY,               -- uuid (generated by the frontend so autosave can upsert directly)
    mailbox     TEXT NOT NULL DEFAULT '',       -- sending identity (the value of the "From" dropdown when composing)
    mode        TEXT NOT NULL DEFAULT 'new',    -- new | reply | forward (determines the title and buttons on restore)
    source_id   TEXT,                           -- original message id when replying/forwarding
    to_emails   TEXT NOT NULL DEFAULT '[]',     -- JSON array
    cc          TEXT,                           -- JSON array, NULL when empty
    bcc         TEXT,                           -- JSON array, NULL when empty
    subject     TEXT,
    body_html   TEXT,
    body_text   TEXT,
    rich        INTEGER NOT NULL DEFAULT 0,     -- whether the body is in rich-text mode (kept consistent on restore)
    updated_at  INTEGER NOT NULL,               -- list sort key (drafts ordered by "last modified" descending)
    created_at  INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_drafts_updated ON drafts(updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_drafts_mailbox ON drafts(mailbox, updated_at DESC);
